242	    private void syncToggleSaveRemovePlaylist(Video original, String playlistId) {
243	        Video video = Video.from(original);
244	
245	        // Need correct playlist title to further comparison (decide whether save or remove)
246	        if (original.getGroup() != null && original.belongsToSamePlaylistGroup()) {
247	            video.title = original.getGroup().getTitle();
248	        }
249	
250	        if (!original.hasPlaylist() && playlistId != null) {
251	            video.playlistId = playlistId;
252	        }
253	
254	        toggleSaveRemovePlaylist(video);
255	    }
