257	    private void toggleSaveRemovePlaylist(Video video) {
258	        mServiceManager.loadPlaylists(video, group -> {
259	            if (group.getMediaItems() == null)
260	                return;
261	
262	            boolean isSaved = false;
263	
264	            for (MediaItem playlist : group.getMediaItems()) {
265	                if (playlist.getTitle().contains(video.getTitle())) {
266	                    isSaved = true;
267	                    break;
268	                }
269	            }
270	
271	            if (isSaved && video.belongsToUserPlaylists()) { // allow deletion only from the Playlists section
272	                if (video.playlistId == null) {
273	                    MessageHelpers.showMessage(getContext(), R.string.cant_delete_empty_playlist);
274	                } else {
275	                    AppDialogUtil.showConfirmationDialog(getContext(), getContext().getString(R.string.remove_playlist_fmt, video.title), () -> {
276	                        removePlaylist(video);
277	                        closeDialog();
278	                    });
279	                }
280	            } else {
281	                savePlaylist(video);
282	            }
283	        });
284	    }
